{
  "operations": [
    {
      "column": "Order ID",
      "operation": "deduplicate",
      "strategy": "keep_most_complete",
      "rationale": "Duplicate records present based on unique counts versus row counts."
    },
    {
      "column": "OrderDate",
      "operation": "parse_date",
      "strategy": "standardize_date",
      "rationale": "Contains inconsistent date string formats across records."
    },
    {
      "column": "Customer Name",
      "operation": "fill_null",
      "strategy": "placeholder_replacement",
      "rationale": "Missing PII values should be replaced with placeholders rather than statistical estimates."
    },
    {
      "column": "customer_email",
      "operation": "fill_null",
      "strategy": "null_invalid_email",
      "rationale": "Contains malformed email formats and null values in PII column."
    },
    {
      "column": "Cust_Phone",
      "operation": "fill_null",
      "strategy": "placeholder_replacement",
      "rationale": "Missing phone numbers should be filled with a placeholder."
    },
    {
      "column": "Shipping Address",
      "operation": "trim_whitespace",
      "strategy": "strip",
      "rationale": "Address entries contain leading and trailing whitespace padding."
    },
    {
      "column": "Country",
      "operation": "normalize",
      "strategy": "normalize_categorical",
      "rationale": "Mixed casing observed in categorical country names."
    },
    {
      "column": "Category",
      "operation": "normalize",
      "strategy": "normalize_categorical",
      "rationale": "Inconsistent casing present in product categories."
    },
    {
      "column": "Quantity",
      "operation": "fill_null",
      "strategy": "median",
      "rationale": "Numeric column with missing values within 2% to 50% threshold."
    },
    {
      "column": "Unit Price",
      "operation": "cast_type",
      "strategy": "safe_numeric_cast",
      "rationale": "Currency symbols and mixed text string formatting present in numeric price field."
    },
    {
      "column": "Discount (%)",
      "operation": "fill_null",
      "strategy": "median",
      "rationale": "Missing numeric discount values require median imputation."
    },
    {
      "column": "Tax Amount",
      "operation": "fill_null",
      "strategy": "median",
      "rationale": "Missing numeric tax amounts require median imputation."
    },
    {
      "column": "Total Amount",
      "operation": "cast_type",
      "strategy": "safe_numeric_cast",
      "rationale": "Numeric total amount stored as VARCHAR requires casting."
    },
    {
      "column": "Payment Method",
      "operation": "normalize",
      "strategy": "normalize_categorical",
      "rationale": "Inconsistent capitalization and formatting across payment methods."
    },
    {
      "column": "Payment Status",
      "operation": "normalize",
      "strategy": "normalize_categorical",
      "rationale": "Mixed casing in payment status categorical values."
    },
    {
      "column": "Shipping Method",
      "operation": "normalize",
      "strategy": "normalize_categorical",
      "rationale": "Mixed casing in shipping method categorical values."
    },
    {
      "column": "Shipping Cost",
      "operation": "cast_type",
      "strategy": "safe_numeric_cast",
      "rationale": "Numeric shipping cost stored as VARCHAR requiring clean numeric cast."
    },
    {
      "column": "Order Status",
      "operation": "normalize",
      "strategy": "normalize_categorical",
      "rationale": "Inconsistent text casing across order status entries."
    },
    {
      "column": "Delivery Date",
      "operation": "parse_date",
      "strategy": "standardize_date",
      "rationale": "Date strings stored in VARCHAR format need date standardization."
    },
    {
      "column": "Region",
      "operation": "fill_null",
      "strategy": "mode",
      "rationale": "Missing values in categorical region column within acceptable threshold."
    },
    {
      "column": "Customer Rating",
      "operation": "cast_type",
      "strategy": "safe_numeric_cast",
      "rationale": "Rating field stored as string containing non-numeric symbols."
    },
    {
      "column": "Notes",
      "operation": "drop_column",
      "strategy": "drop_all_null_rows",
      "rationale": "Column contains over 50% missing values and is non-essential."
    }
  ]
}
